from pathlib import Path
import subprocess,json,hashlib,time

p=Path(__file__).parent
original=json.loads((p/'windows-original-first/windows-observations-first.json').read_text())
upload=json.loads((p/'root-native-upload-first.stdout').read_text(encoding='utf-8-sig'))
expected=[{'name':f['name'],'sha256':f['sha256']} for f in upload['files']]
expected.append({'name':'windows-observations-first.json','sha256':hashlib.sha256((p/'windows-original-first/windows-observations-first.json').read_bytes()).hexdigest()})
ps=r'''$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false);$root=Join-Path ([IO.Path]::GetTempPath()) 'FutureClassroomMsiOwner-e3365555af2a409eba9bb94ab37b0e28';$owner='future-classroom-owned-r60-msi-native/v1:e3365555af2a409eba9bb94ab37b0e28';if((Get-Item -LiteralPath $root -Force).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Reparse root'};if([IO.File]::ReadAllText((Join-Path $root '.owner')) -cne $owner){throw 'Wrong root owner'};$expected=__EXPECTED__ | ConvertFrom-Json;$files=@(Get-ChildItem -LiteralPath $root -Force);if($files.Count -ne $expected.Count){throw 'Unknown file count'};foreach($f in $files){$rows=@($expected|Where-Object{$_.name -ceq $f.Name});if($rows.Count -ne 1 -or $f.PSIsContainer -or ($f.Attributes -band [IO.FileAttributes]::ReparsePoint) -or (Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash.ToLowerInvariant() -cne $rows[0].sha256){throw 'Unknown file identity'}};if(@(Get-Process msiexec -ErrorAction SilentlyContinue).Count -ne 0){throw 'MSI process still present; retain'};$old=Get-Process -Id 35120 -ErrorAction SilentlyContinue;if($old){try{if($old.StartTime.ToUniversalTime().ToFileTimeUtc() -eq 134379832930466020){throw 'Exact original still live'}}finally{$old.Dispose()}};$psi=[Diagnostics.ProcessStartInfo]::new();$psi.FileName=Join-Path $root 'guardian.exe';$psi.Arguments='--product-state';$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;$q=[Diagnostics.Process]::new();$q.StartInfo=$psi;if(-not $q.Start()){throw 'Query not started'};if(-not $q.WaitForExit(5000)){throw 'Query unresolved; preserve'};$query=[ordered]@{pid=$q.Id;actualExit=$true;exitCode=$q.ExitCode;stdout=$q.StandardOutput.ReadToEnd();stderr=$q.StandardError.ReadToEnd()};$q.Dispose();$state=$query.stdout|ConvertFrom-Json;if($query.exitCode -ne 0 -or $query.stderr -cne '' -or $state.productState -ne -1 -or $state.productCode -cne '{51C60258-197D-4EA2-8859-F59ABA07AC38}' -or $state.nonce -cne 'e3365555af2a409eba9bb94ab37b0e28'){throw 'Original fixed product not absent'};$sid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;if($sid -cne 'S-1-5-21-3896111207-1867804362-1971593122-1001'){throw 'Wrong user'};$b=[Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::CurrentUser,[Microsoft.Win32.RegistryView]::Registry32);$key='Software\FutureClassroom-MsiGuardian-Test-e3365555af2a409eba9bb94ab37b0e28';$k=$b.OpenSubKey($key,$true);if(-not $k){throw 'Missing owned root'};try{if(@($k.GetSubKeyNames()).Count -ne 0 -or @($k.GetValueNames()).Count -ne 4){throw 'Unexpected transaction evidence or payload; retain'};foreach($name in @('ProbeNonce','OwnerSid','CurrentOperation')){if($k.GetValueKind($name) -ne [Microsoft.Win32.RegistryValueKind]::String){throw 'Wrong marker kind'}};if($k.GetValueKind('Decision') -ne [Microsoft.Win32.RegistryValueKind]::DWord -or $k.GetValue('Decision') -ne 1 -or $k.GetValue('ProbeNonce') -cne 'e3365555af2a409eba9bb94ab37b0e28' -or $k.GetValue('OwnerSid') -cne $sid -or $k.GetValue('CurrentOperation') -cne 'c8d7b6575126430e8e432d3c0508071c'){throw 'Marker mismatch'};$b.DeleteSubKey($key,$true)}finally{$k.Dispose()};$left=$b.OpenSubKey($key,$false);if($left){$left.Dispose();throw 'Registry retained'};$b.Dispose();foreach($f in $files){[IO.File]::Delete($f.FullName)};[IO.Directory]::Delete($root,$false);@{status='PASS_FAILED_PROBE_OWNED_CLEANUP';originalOperation='FAIL_TIMEOUT_NOT_RECLASSIFIED';originalProcessCurrentlyAbsent=$true;allMsiexecCurrentlyAbsent=$true;fixedProductQuery=$query;registryAbsent=$true;directoryAbsent=(-not(Test-Path -LiteralPath $root));deletedFiles=$expected;sshd=(Get-Service sshd).Status.ToString();sharedServiceKilled=$false;nextMsiStarted=$false}|ConvertTo-Json -Depth 8 -Compress;'''
ps=ps.replace('__EXPECTED__', "'"+json.dumps(expected,separators=(',',':')).replace("'","''")+"'")
label=p/'root-native-failed-cleanup-first'
label.with_suffix('.input.ps1').write_text(ps+'\n')
start=time.monotonic();r=subprocess.run(['ssh','-T','-o','BatchMode=yes','future-classroom-win11','powershell -NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass -Command -'],input=(ps+'\n').encode(),capture_output=True,timeout=30)
