report={'sshExitCode':r.returncode,'elapsedSeconds':time.monotonic()-start,'stdoutSha256':hashlib.sha256(r.stdout).hexdigest(),'original':json.loads(r.stdout.decode('utf-8-sig')) if r.returncode==0 else None}
label.with_suffix('.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report));print(r.stderr.decode('utf-8-sig'))
assert r.returncode==0 and report['original']['status']=='PASS_FAILED_PROBE_OWNED_CLEANUP'
